client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  if (doc && doc.name) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#fce4ec;color:#880e4f;border-left:4px solid #e91e63;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">R\u00e9f. PV-RET : ' + doc.name + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
  var roles = (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ? frappe.boot.user.roles : [];
  var state = (doc && (doc.workflow_state || doc.statut)) || 'Brouillon';
  var rules = {
    'signature_retourneur': { states: ['Brouillon'], roles: [] },
    'retourneur_nom': { states: ['Brouillon'], roles: [] },
    'signature_magasin': { states: ['En attente Magasin'], roles: ['Stock Manager','Stock User','Charg\u00e9 des Stocks','System Manager'] }
  };
  ['signature_retourneur','signature_magasin'].forEach(function(f){ try{ frappe.web_form.set_df_property(f,'read_only',1); }catch(e){} });
  Object.keys(rules).forEach(function(field) {
    var rule = rules[field];
    var stateOk = rule.states.indexOf(state) !== -1;
    var roleOk = rule.roles.length === 0 || rule.roles.some(function(r){ return roles.indexOf(r) !== -1; });
    if (stateOk && roleOk) { try{ frappe.web_form.set_df_property(field,'read_only',0); }catch(e){} }
  });
  if (doc && doc.statut) {
    var cm = {'Approuv\u00e9':'#2e7d32','Rejet\u00e9':'#c62828','Brouillon':'#757575','En attente Magasin':'#e65100'};
    var c = cm[doc.statut] || '#880e4f';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;">\u00c9tat\u00a0: '+doc.statut+'</div>';
    var w2 = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w2) w2.prepend(el);
  }
};
frappe.web_form.on('load', function(){
  // retourneur_nom est auto-rempli par le serveur depuis le PV Sortie d'origine
});
frappe.web_form.on('pv_sortie_origine', function(field, value){
  if (!value) return;
  frappe.call({
    method: 'frappe.client.get_value',
    args: { doctype: 'PV Sortie Materiel', filters: { name: value }, fieldname: ['project', 'customer', 'customer_manuel'] },
    callback: function(r) {
      if (!r || !r.message) return;
      if (r.message.project) frappe.web_form.set_value('project', r.message.project);
      if (r.message.customer) frappe.web_form.set_value('customer', r.message.customer);
      if (r.message.customer_manuel && !r.message.customer) frappe.web_form.set_value('customer_libre', r.message.customer_manuel);
    }
  });
});
